<script setup lang="ts">
import {
  ClearOutlined,
  DeleteOutlined,
  EditOutlined,
  PlusOutlined,
  ReloadOutlined,
  SearchOutlined,
} from '@ant-design/icons-vue';
import { useAccess } from '@vben/access';
import { message, Modal, type FormInstance } from 'ant-design-vue';
import { computed, onMounted, reactive, ref } from 'vue';

import {
  createReport,
  deleteReport,
  getReportList,
  updateReport,
  type Report,
  type ReportPayload,
} from '#/api/kadmin/generated/report';

type TablePagination = { current?: number; pageSize?: number };

const { hasAccessByCodes } = useAccess();
const canCreate = computed(() => hasAccessByCodes(['system:report:create', '*']));
const canUpdate = computed(() => hasAccessByCodes(['system:report:update', '*']));
const canDelete = computed(() => hasAccessByCodes(['system:report:delete', '*']));

const loading = ref(false);
const errorText = ref('');
const items = ref<Report[]>([]);
const total = ref(0);
const page = ref(1);
const pageSize = ref(20);

const filters = reactive<Record<string, string>>({
  reason: '',
  result: '',
  createBy: '',
  createTime: '',
  updateBy: '',
  updateTime: '',
  remark: '',
});

const columns = [
  { title: 'Report Id', dataIndex: 'reportId', key: 'reportId', width: 160, ellipsis: true },
  { title: 'File Id', dataIndex: 'fileId', key: 'fileId', width: 160, ellipsis: true },
  { title: 'User Id', dataIndex: 'userId', key: 'userId', width: 160, ellipsis: true },
  { title: 'Reason', dataIndex: 'reason', key: 'reason', width: 160, ellipsis: true },
  { title: '审核结果（0未审核 1属实 2不属实）', dataIndex: 'result', key: 'result', width: 160, ellipsis: true },
  { title: 'Create By', dataIndex: 'createBy', key: 'createBy', width: 160, ellipsis: true },
  { title: 'Create Time', dataIndex: 'createTime', key: 'createTime', width: 160, ellipsis: true },
  { title: 'Update By', dataIndex: 'updateBy', key: 'updateBy', width: 160, ellipsis: true },
  { title: 'Update Time', dataIndex: 'updateTime', key: 'updateTime', width: 160, ellipsis: true },
  { title: 'Remark', dataIndex: 'remark', key: 'remark', width: 160, ellipsis: true },
  { title: '操作', key: 'action', width: 120, fixed: 'right' },
];

const pagination = computed(() => ({
  current: page.value,
  pageSize: pageSize.value,
  pageSizeOptions: ['10', '20', '50', '100'],
  showSizeChanger: true,
  showTotal: (value: number) => `共 ${value} 条`,
  total: total.value,
}));

async function fetchList() {
  loading.value = true;
  errorText.value = '';
  try {
    const result = await getReportList({
      page: page.value,
      pageSize: pageSize.value,
      reason: filters.reason || undefined,
      result: filters.result || undefined,
      createBy: filters.createBy || undefined,
      createTime: filters.createTime || undefined,
      updateBy: filters.updateBy || undefined,
      updateTime: filters.updateTime || undefined,
      remark: filters.remark || undefined,
    });
    items.value = result.items;
    total.value = result.total;
  } catch (error) {
    errorText.value = error instanceof Error ? error.message : '加载失败';
  } finally {
    loading.value = false;
  }
}

function search() {
  page.value = 1;
  void fetchList();
}

function resetSearch() {
  filters.reason = '';
  filters.result = '';
  filters.createBy = '';
  filters.createTime = '';
  filters.updateBy = '';
  filters.updateTime = '';
  filters.remark = '';
  search();
}

function handleTableChange(paginationValue: TablePagination) {
  page.value = paginationValue.current ?? 1;
  pageSize.value = paginationValue.pageSize ?? 20;
  void fetchList();
}

const modalOpen = ref(false);
const submitting = ref(false);
const editingId = ref<null | number>(null);
const formRef = ref<FormInstance>();
const dirty = ref(false);

const formState = reactive<Record<string, any>>({
  fileId: undefined,
  userId: undefined,
  reason: '',
  result: '',
  createBy: '',
  createTime: '',
  updateBy: '',
  updateTime: '',
  remark: '',
});

const rules: Record<string, unknown> = {
  fileId: [{ required: true, message: '请输入File Id', trigger: 'blur' }],
  userId: [{ required: true, message: '请输入User Id', trigger: 'blur' }],
  reason: [{ required: true, message: '请输入Reason', trigger: 'blur' }],
};

function openCreate() {
  editingId.value = null;
  dirty.value = false;
  formState.fileId = undefined;
  formState.userId = undefined;
  formState.reason = '';
  formState.result = '';
  formState.createBy = '';
  formState.createTime = '';
  formState.updateBy = '';
  formState.updateTime = '';
  formState.remark = '';
  modalOpen.value = true;
}

async function openEdit(record: Report) {
  editingId.value = record.reportId;
  dirty.value = false;
  formState.fileId = record.fileId;
  formState.userId = record.userId;
  formState.reason = record.reason;
  formState.result = record.result;
  formState.createBy = record.createBy;
  formState.createTime = record.createTime;
  formState.updateBy = record.updateBy;
  formState.updateTime = record.updateTime;
  formState.remark = record.remark;
  modalOpen.value = true;
}

function requestClose() {
  if (!dirty.value) {
    modalOpen.value = false;
    return;
  }
  Modal.confirm({
    title: '放弃修改？',
    content: '当前表单有未保存的修改。',
    okText: '放弃',
    okType: 'danger',
    cancelText: '继续编辑',
    onOk: () => {
      dirty.value = false;
      modalOpen.value = false;
    },
  });
}

function markDirty() {
  if (modalOpen.value) {
    dirty.value = true;
  }
}

async function submit() {
  try {
    await formRef.value?.validate();
  } catch {
    return;
  }
  submitting.value = true;
  try {
    const payload = {
      fileId: formState.fileId,
      userId: formState.userId,
      reason: formState.reason,
      result: formState.result,
      createBy: formState.createBy,
      createTime: formState.createTime,
      updateBy: formState.updateBy,
      updateTime: formState.updateTime,
      remark: formState.remark,
    } as ReportPayload;
    if (editingId.value === null) {
      await createReport(payload);
      message.success('新增成功');
    } else {
      await updateReport(editingId.value, payload);
      message.success('修改成功');
    }
    modalOpen.value = false;
    dirty.value = false;
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '提交失败');
  } finally {
    submitting.value = false;
  }
}

async function remove(record: Report) {
  try {
    await deleteReport(record.reportId);
    message.success('删除成功');
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '删除失败');
  }
}

onMounted(() => {
  void fetchList();
});
</script>
